// ORDER TO SHIP ENGINE — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 capture and confirm" and
// "02 progress and ship"). If you change it in one, paste it into the other — build.py
// regenerates both from this one file, so normally you never have to.
//
// A blank key or a false flag means that step is SKIPPED, never that the run fails.
// That is what lets this be demonstrated on a screen-share before a single credential
// exists.

// ---------------------------------------------------------------- The production board
// The Google Sheet the team already runs as their production board. The id is the long
// code in the sheet's web address:
// docs.google.com/spreadsheets/d/<THIS BIT>/edit
const BOARD_SHEET_ID = '';
const BOARD_TAB      = 'Orders';

// Set to true only when ALL of these are in place:
//   1. the sheet exists with the headings below (see sheet/Orders.csv)
//   2. BOARD_SHEET_ID above is filled in
//   3. the [cred] Sheets nodes in both workflows have Google credentials attached
// Until then the workflows run against a built-in demo board: rows are shown in
// STOP nodes instead of being written, and fabricated customers can never be emailed.
const BOARD_READY = false;

// The column headings, exactly as they appear in row 1 of the Orders tab.
// 'Items (json)' holds the line items as JSON so the board stays one row per order.
const COLUMNS = {
  order_key:         'Order key',
  source:            'Source',
  order_id:          'Order no.',
  placed:            'Placed',
  customer:          'Customer',
  email:             'Email',
  items:             'Items (json)',
  spec:              'Spec',
  window_start:      'Ship window start',
  window_end:        'Ship window end',
  stage:             'Stage',
  confirmation_sent: 'Confirmation sent',
  carrier:           'Carrier',
  tracking:          'Tracking no.',
  ship_date:         'Shipped date',
  ship_email_sent:   'Ship email sent',
  notes:             'Notes'
};

// The stages the team moves a row through. The workflow writes 'New order' when the row
// lands and 'Confirmed' once the confirmation email is away; the OFFICE moves rows to
// 'In production' and finally 'Shipped' (when a label exists). That last flip is what
// triggers the shipping email. Nothing ships before a confirmation was recorded.
const STAGE_ON_ARRIVAL = 'New order';
const STAGE_CONFIRMED  = 'Confirmed';
const STAGE_SHIPPED    = 'Shipped';
const STAGES = ['New order', 'Confirmed', 'In production', 'Shipped', 'Delivered',
  'On hold', 'Cancelled'];

// ---------------------------------------------------------------- The stores
// Which store webhooks feed this. Square is in DEPOSIT_SOURCES: for designer/custom
// goods the post says the workflow may begin when the deposit is received, so a Square
// order whose payment has not landed is held until it has. Shopify and Etsy orders only
// arrive here once the store marks them confirmed/paid, so they are not gated.
const SOURCE_LABELS = { shopify: 'Shopify', etsy: 'Etsy', square: 'Square' };
const DEPOSIT_SOURCES = ['square'];

// ---------------------------------------------------------------- Product rules
// The rules/formulas the client provides, in one table so every number an email quotes
// can be traced back to a rule. Each order line is looked up by sku.
//
//   lead_days  how many working days this piece takes to build. The confirmation email's
//              ship window = order date + the LONGEST lead in the order + the buffers
//              below. Nothing ships before its promise, so the window is the honest one.
//   anchors    the wall hardware the customer needs for installation:
//                { mode: 'none' }        free-standing piece — no wall anchors
//                { mode: 'fixed', qty }  per unit (e.g. a bracket kit = 8 anchors)
//                { mode: 'per_metre' }   qty per metre of the line's length, rounded up
//   manual     the installation manual URL for that product
const PRODUCT_RULES = [
  { sku: 'DIN-TBL-WALNUT-6', name: 'Walnut dining table, 6-seat', lead_days: 14,
    anchors: { mode: 'none' }, manual: '', note: 'Free-standing piece — no wall anchors.' },
  { sku: 'CON-OAK-160', name: 'Oak console, 160 cm', lead_days: 10,
    anchors: { mode: 'none' }, manual: '', note: 'Free-standing piece — no wall anchors.' },
  { sku: 'SHLF-OAK-120', name: 'Oak wall shelf, 120 cm', lead_days: 6,
    anchors: { mode: 'per_metre', qty: 2 }, manual: 'https://example.com/manuals/oak-shelf-120.pdf',
    note: 'Two brackets supplied; fixings sized for the wall type.' },
  { sku: 'BRK-STEEL-L', name: 'Steel L-bracket set (pair)', lead_days: 3,
    anchors: { mode: 'fixed', qty: 8 }, manual: '',
    note: 'Four anchors per bracket; use the template supplied.' }
];

// A line item whose sku is NOT in the table above cannot be given an honest ship window
// or an honest anchor count. true = hold the order and show it in a STOP node instead of
// promising something the rules cannot support. Add the missing sku to PRODUCT_RULES and
// re-run.
const HOLD_UNRULED_ITEMS = true;

// The shipping promise, in working days (Mon-Fri):
//   earliest = order date + longest lead in the order + START buffer
//   latest   = order date + longest lead in the order + END buffer
// The email quotes the window, never a single date.
const WINDOW_BUFFER_START_DAYS = 3;
const WINDOW_BUFFER_END_DAYS   = 8;

// ---------------------------------------------------------------- Sending
const COMPANY_NAME = 'Example Furniture Co';
const FROM_NAME    = 'Example Furniture Co';
const REPLY_TO     = '';          // where customer replies should land
const PHONE        = '';
const WEBSITE      = '';

// The personalised emails. The braces are filled in code from the order and the rules —
// the model is never asked to invent a date, an anchor count or a manual link.
const CONFIRM_SUBJECT = 'Your {company} order {order} — thank you';
const SHIP_SUBJECT    = 'Your {company} order {order} has shipped';

// ---------------------------------------------------------------- ShipStation
// Optional. When the office creates a label in ShipStation they flip the board row to
// 'Shipped'; this workflow then tries to pull carrier, tracking number and ship date
// from ShipStation instead of asking anyone to type them.
//
// Set true only when: the [cred] ShipStation node has credentials attached AND the
// fetch path has been checked against your ShipStation account (see README — the
// endpoint is the one integration point to confirm on a live account).
const SHIPSTATION_READY = false;
const SHIPSTATION_BASE  = 'https://api.shipstation.com';

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_EMAIL blank -> PREVIEW. Rows are written to the sheet (when
//                                      BOARD_READY) but no email is sent. Ships this way.
//   TEST_RUN true,  TEST_EMAIL set   -> TEST. Emails really send, but every one goes to
//                                      TEST_EMAIL instead of the customer.
//   TEST_RUN false                   -> LIVE. Customers get the real thing.
const TEST_RUN   = true;
const TEST_EMAIL = '';

// While the demo board is in use (no sheet configured) the run is FORCED into preview:
// a fabricated customer can never be emailed, whatever TEST_RUN says.
const DEMO_MODE = BOARD_READY !== true;

let MODE = TEST_RUN !== true ? 'live'
  : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');
if (DEMO_MODE && MODE !== 'preview') MODE = 'preview';

// ---------------------------------------------------------------- Demo board
// The rows the workflows run against until BOARD_READY is set. Every customer, order and
// product here is fabricated. The mix is deliberate — it has to be able to show every
// gate doing its job:
//   * a 'Shipped' row that was confirmed and has tracking pasted   -> shipping email
//   * a 'Shipped' row with NO tracking and no ShipStation          -> STOP: tracking missing
//   * a 'Shipped' row that was never confirmed                     -> STOP: never shipped unconfirmed
//   * a finished row already emailed                               -> left alone (idempotent)
//   * open rows in production / new                                -> left alone
const DEMO_ORDERS = [
  {
    order_key: 'shopify|5102', source: 'shopify', order_id: '5102', placed: '2026-09-02 09:41',
    customer: 'Dana Whitfield', email: 'user@example.com',
    items: '[{"sku":"DIN-TBL-WALNUT-6","name":"Walnut dining table, 6-seat","qty":1,"dim_m":"","spec":"2200 x 1000 x 750 mm, matte oil finish"},{"sku":"BRK-STEEL-L","name":"Steel L-bracket set (pair)","qty":2,"dim_m":"","spec":""}]',
    spec: '', window_start: '2026-09-23', window_end: '2026-09-30', stage: 'In production',
    confirmation_sent: '2026-09-02 09:41', carrier: '', tracking: '', ship_date: '',
    ship_email_sent: '', notes: ''
  },
  {
    order_key: 'etsy|2218', source: 'etsy', order_id: '2218', placed: '2026-09-04 14:02',
    customer: 'Marlon Reyes', email: 'user@example.com',
    items: '[{"sku":"SHLF-OAK-120","name":"Oak wall shelf, 120 cm","qty":1,"dim_m":"1.2","spec":"120 x 22 x 4 cm"},{"sku":"BRK-STEEL-L","name":"Steel L-bracket set (pair)","qty":1,"dim_m":"","spec":""}]',
    spec: '', window_start: '2026-09-18', window_end: '2026-09-25', stage: 'Shipped',
    confirmation_sent: '2026-09-04 14:02', carrier: 'UPS', tracking: '1Z999AA10123456784',
    ship_date: '2026-09-16', ship_email_sent: '', notes: ''
  },
  {
    order_key: 'shopify|5117', source: 'shopify', order_id: '5117', placed: '2026-09-05 16:30',
    customer: 'Priya Nair', email: 'user@example.com',
    items: '[{"sku":"CON-OAK-160","name":"Oak console, 160 cm","qty":1,"dim_m":"","spec":"160 x 40 x 75 cm, no back panel"}]',
    spec: '', window_start: '2026-09-22', window_end: '2026-09-29', stage: 'Shipped',
    confirmation_sent: '2026-09-05 16:30', carrier: '', tracking: '', ship_date: '',
    ship_email_sent: '', notes: ''
  },
  {
    order_key: 'square|ORD-9081', source: 'square', order_id: 'ORD-9081', placed: '2026-09-08 11:12',
    customer: 'Tom Okafor', email: 'user@example.com',
    items: '[{"sku":"DIN-TBL-WALNUT-6","name":"Walnut dining table, 6-seat","qty":1,"dim_m":"","spec":"custom width 2400 mm"}]',
    spec: 'Custom width 2400 mm', window_start: '2026-09-28', window_end: '2026-10-05',
    stage: 'Shipped', confirmation_sent: '', carrier: '', tracking: '', ship_date: '',
    ship_email_sent: '', notes: ''
  },
  {
    order_key: 'shopify|5123', source: 'shopify', order_id: '5123', placed: '2026-09-09 08:05',
    customer: 'Elena Rossi', email: 'user@example.com',
    items: '[{"sku":"SHLF-OAK-120","name":"Oak wall shelf, 120 cm","qty":2,"dim_m":"1.2","spec":""}]',
    spec: '', window_start: '2026-09-22', window_end: '2026-09-29', stage: 'New order',
    confirmation_sent: '', carrier: '', tracking: '', ship_date: '', ship_email_sent: '',
    notes: ''
  },
  {
    order_key: 'etsy|2190', source: 'etsy', order_id: '2190', placed: '2026-08-28 10:15',
    customer: 'June Park', email: 'user@example.com',
    items: '[{"sku":"CON-OAK-160","name":"Oak console, 160 cm","qty":1,"dim_m":"","spec":""}]',
    spec: '', window_start: '2026-09-14', window_end: '2026-09-21', stage: 'Delivered',
    confirmation_sent: '2026-08-28 10:15', carrier: 'FedEx', tracking: '778899001122',
    ship_date: '2026-09-15', ship_email_sent: '2026-09-15 09:30', notes: ''
  }
];

return [{
  json: {
    company_name: COMPANY_NAME,
    from_name:    FROM_NAME,
    reply_to:     REPLY_TO.trim(),
    phone:        PHONE.trim(),
    website:      WEBSITE.trim(),

    board_sheet_id: BOARD_SHEET_ID.trim(),
    board_tab:      BOARD_TAB,
    columns:        COLUMNS,
    board_ready:    BOARD_READY === true,

    source_labels:  SOURCE_LABELS,
    deposit_sources: DEPOSIT_SOURCES,

    product_rules:    PRODUCT_RULES,
    hold_unruly:      HOLD_UNRULED_ITEMS === true,
    window_start_days: Number(WINDOW_BUFFER_START_DAYS) || 0,
    window_end_days:   Number(WINDOW_BUFFER_END_DAYS) || 0,

    stage_on_arrival: STAGE_ON_ARRIVAL,
    stage_confirmed:  STAGE_CONFIRMED,
    stage_shipped:    STAGE_SHIPPED,
    stages:           STAGES,

    confirm_subject: CONFIRM_SUBJECT,
    ship_subject:    SHIP_SUBJECT,

    shipstation_ready: SHIPSTATION_READY === true,
    shipstation_base:  SHIPSTATION_BASE,

    demo_orders: DEMO_ORDERS,
    demo_mode:   DEMO_MODE,

    // derived flags — the gates read these, never the raw constants
    mode:          MODE,
    preview_only:  MODE === 'preview',
    test_send:     MODE === 'test',
    live_send:     MODE === 'live',
    send_enabled:  MODE !== 'preview',
    test_email:    TEST_EMAIL.trim()
  }
}];

// No sheet configured yet: emit the built-in demo board rows instead. Rows come out keyed
// by the same HEADINGS a Google Sheets read would produce, so everything downstream is
// identical whether the data is real or fabricated. Every customer here is invented.
const cfg = $('config').first().json;
const cols = cfg.columns || {};
const rows = (cfg.demo_orders || []).map(function (o) {
  const row = {};
  for (const k of Object.keys(cols)) row[cols[k]] = (o[k] != null ? String(o[k]) : '');
  row._demo = true;
  return row;
});
return rows.map((r) => ({ json: r }));

// The morning board run: one read of the whole Orders tab, classified in one place.
// Every row the office has flipped to 'Shipped' but that we have not yet emailed gets a
// shipping email; a 'Shipped' row with no confirmation recorded is HELD, never emailed —
// an order is never shipped unconfirmed, and the board is what proves the confirmation
// happened. Rows already emailed, still in production, or finished are left alone, so a
// run is idempotent: nothing is emailed twice.
const cfg = $('config').first().json;
const cols = cfg.columns || {};
const h = (k) => cols[k] || k;
const shipped = (cfg.stage_shipped || 'Shipped');

const toShip = [];
const unconfirmed = [];
let rowsRead = 0;

for (const row of $input.all().map((i) => i.json)) {
  const stage = String(row[h('stage')] || '').trim();
  if (!stage) continue;
  rowsRead++;
  const confirmed = String(row[h('confirmation_sent')] || '').trim();
  const emailed = String(row[h('ship_email_sent')] || '').trim();
  if (stage !== shipped) continue;                       // still in production, or finished
  if (!confirmed) { unconfirmed.push(row); continue; }   // flipped early — hold, do not email
  if (emailed) continue;                                 // already done — idempotent
  toShip.push(Object.assign({}, row, {
    _tracking_pasted: String(row[h('tracking')] || '').trim() !== ''
  }));
}

return [{
  json: {
    rows_read: rowsRead,
    to_ship: toShip,
    unconfirmed: unconfirmed,
    _has_to_ship: toShip.length > 0,
    _has_unconfirmed: unconfirmed.length > 0
  }
}];

// Nothing on the board needs this run: no rows flipped to Shipped that are waiting on an
// email, nothing shipped before it was confirmed. The run still completes cleanly.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, { _outcome: 'nothing_to_do' })
}));

// One item per order that needs its shipping email, so the downstream send runs once per
// order rather than once per run.
const item = $input.first().json;
return (item.to_ship || []).map((row) => ({ json: Object.assign({}, row, { _ship: true }) }));

// The office pasted carrier/tracking/ship date onto the row when they made the label, so
// no API call is needed. The values travel as-is — no guessing, no reshaping.
const cfg = $('config').first().json;
const cols = cfg.columns || {};
const h = (k) => cols[k] || k;
const item = $input.first().json;
const carrier = String(item[h('carrier')] || '').trim();
const tracking = String(item[h('tracking')] || '').trim();
const shipDate = String(item[h('ship_date')] || '').trim();
return [{
  json: Object.assign({}, item, {
    carrier: carrier,
    tracking: tracking,
    ship_date: shipDate,
    _tracking_found: tracking !== '',
    _tracking_source: 'board',
    _reason: tracking ? '' : 'no tracking number pasted on the row'
  })
}];

// Maps the ShipStation reply onto the row. ShipStation's response shape changes between
// API versions, so the lookup is by common field names rather than one fixed path — the
// endpoint itself is the integration point to confirm on the live account (see README).
function dig(obj, keys, depth) {
  if (!obj || typeof obj !== 'object' || depth > 5) return '';
  for (const key of keys) {
    if (obj[key] != null && String(obj[key]) !== '') return String(obj[key]);
  }
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v && typeof v === 'object') {
      const hit = dig(v, keys, depth + 1);
      if (hit) return hit;
    }
  }
  return '';
}

const cfg = $('config').first().json;
const cols = cfg.columns || {};
const h = (k) => cols[k] || k;
const item = $input.first().json;
const body = (item && typeof item === 'object') ? item : {};

const tracking = dig(body, ['trackingNumber', 'tracking_number', 'tracking']);
const carrier = dig(body, ['carrierCode', 'carrier_code', 'carrier']);
const shipDate = dig(body, ['shipDate', 'ship_date']);

const found = tracking !== '';
return [{
  json: Object.assign({}, item, {
    carrier: found ? carrier : '',
    tracking: found ? tracking : '',
    ship_date: found ? shipDate : '',
    _tracking_found: found,
    _tracking_source: 'shipstation',
    _reason: found ? '' : 'ShipStation returned no shipment for this order number'
  })
}];

// No ShipStation configured and the board row has no tracking number pasted. The run
// stops here for this order rather than emailing a ship notice that cannot carry a number.
const cfg = $('config').first().json;
const item = $input.first().json;
return [{
  json: Object.assign({}, item, {
    _tracking_found: false,
    _tracking_source: 'none',
    _reason: 'no ShipStation credentials and no tracking number on the row'
  })
}];

// No tracking could be found: nothing was pasted on the row and ShipStation (if
// configured) had nothing for the order. The shipping email is NOT sent — a ship notice
// without a tracking number is worse than none, and this is the row the office sees in
// the execution list.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, {
    _outcome: 'held',
    _reason: i.json._reason || 'no tracking number available'
  })
}));

// Composes the personalised shipping + installation email for one shipped order. Every
// number in it is computed here from PRODUCT_RULES and the row's own line items — the
// anchor counts and manual links are rules in config, not prose. If a rule is missing,
// that line says the guide travels with the shipment instead of inventing a link.
function esc(v) {
  return String(v == null ? '' : v).replace(/[<>&"]/g, function (c) {
    return { '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c];
  });
}
function fmtDate(d) {
  const months = ['January','February','March','April','May','June','July','August',
    'September','October','November','December'];
  const p = String(d || '').split('-');
  if (p.length !== 3) return d || '';
  return (months[Number(p[1]) - 1] || p[1]) + ' ' + Number(p[2]) + ', ' + p[0];
}
function parseItems(raw) {
  try {
    const arr = JSON.parse(raw || '[]');
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}
function anchorsFor(rule, qty, line) {
  const a = rule.anchors || { mode: 'none' };
  if (a.mode === 'none') return { text: 'free-standing — no wall anchors needed', n: 0 };
  if (a.mode === 'fixed') return { text: (Number(a.qty) || 0) * qty + ' anchors',
                                   n: (Number(a.qty) || 0) * qty };
  if (a.mode === 'per_metre') {
    const m = parseFloat(line.dim_m);
    if (!(m > 0)) return { text: 'anchors sized to the length (rule is per metre)', n: -1 };
    const total = m * qty;
    const n = Math.ceil(total * (Number(a.qty) || 0));
    return { text: n + ' anchors (2 per metre over ' + total + ' m)', n: n };
  }
  return { text: '', n: -1 };
}

const cfg = $('config').first().json;
const cols = cfg.columns || {};
const h = (k) => cols[k] || k;
const item = $input.first().json;
const rules = (cfg.product_rules || []).reduce(function (m, r) {
  m[String(r.sku).trim().toLowerCase()] = r;
  return m;
}, {});

const lines = parseItems(item[h('items')]);
const built = lines.map(function (li) {
  const rule = rules[String(li.sku || '').trim().toLowerCase()];
  const qty = Math.max(1, Number(li.qty) || 1);
  if (!rule) return { name: li.name || li.sku, qty: qty,
                      anchor: 'installation guide travels with the shipment',
                      manual: '', note: '' };
  const a = anchorsFor(rule, qty, li);
  return { name: rule.name || li.name, qty: qty, anchor: a.text, manual: rule.manual || '',
           note: rule.note || '' };
});

const anchorRows = built.filter((b) => b.anchor).map(function (b) {
  return '<tr><td style="padding:6px 0">' + esc(b.name) + ' &times; ' + b.qty +
         '</td><td style="padding:6px 0;text-align:right">' + esc(b.anchor) + '</td></tr>';
}).join('');
const manuals = built.map((b) => b.manual).filter((m) => m)
  .filter(function (m, idx, arr) { return arr.indexOf(m) === idx; });
const manualLines = manuals.map(function (m) {
  return '<li><a href="' + esc(m) + '">' + esc(m) + '</a></li>';
}).join('');

const tracking = String(item[h('tracking')] || '').trim();
const carrier = String(item[h('carrier')] || '').trim();
const orderNo = String(item[h('order_id')] || '').trim();

const subject = (cfg.ship_subject || 'Your {company} order {order} has shipped')
  .replace('{company}', cfg.company_name)
  .replace('{order}', orderNo);

const html =
  '<p>Hi ' + esc(item[h('customer')] || 'there') + ',</p>' +
  '<p>Good news — your order has left the workshop' +
  (carrier ? ' with ' + esc(carrier) : '') + '.</p>' +
  '<p><strong>Tracking:</strong> ' + esc(tracking) +
  (carrier ? ' (' + esc(carrier) + ')' : '') +
  (String(item[h('ship_date')] || '').trim()
    ? ' &middot; shipped ' + esc(fmtDate(item[h('ship_date')])) : '') + '</p>' +
  '<h3>What you need for installation</h3>' +
  '<table>' + anchorRows + '</table>' +
  (manualLines ? '<h3>Installation manuals</h3><ul>' + manualLines + '</ul>' : '') +
  '<p>If anything arrives damaged, photograph the packaging before you open it and ' +
  'email us within 48 hours.</p>' +
  '<p>— ' + esc(cfg.from_name || cfg.company_name) + '</p>';

const textLines = built.map(function (b) {
  return '  - ' + b.qty + 'x ' + b.name + ' — ' + b.anchor;
}).join('\n');
const text =
  'Hi ' + (item[h('customer')] || 'there') + ',\n\n' +
  'Good news — your order has left the workshop' +
  (carrier ? ' with ' + carrier : '') + '.\n' +
  'Tracking: ' + tracking + (carrier ? ' (' + carrier + ')' : '') +
  (String(item[h('ship_date')] || '').trim()
    ? ' — shipped ' + fmtDate(item[h('ship_date')]) : '') + '\n\n' +
  'What you need for installation:\n' + textLines + '\n' +
  (manuals.length ? '\nInstallation manuals:\n' +
    manuals.map(function (m) { return '  - ' + m; }).join('\n') + '\n' : '\n') +
  '\n— ' + (cfg.from_name || cfg.company_name);

return [{
  json: Object.assign({}, item, {
    customer_email: item[h('email')] || '',
    customer_subject: subject,
    customer_html: html,
    customer_text: text
  })
}];

// Preview or demo mode: the shipping email was composed but not sent, so the row is NOT
// marked as emailed — the next run will try again, which is right, because nothing went
// out. Open this node to read the email the customer would get.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, {
    _outcome: 'preview',
    _reason: 'preview mode — shipping email composed, not sent'
  })
}));

// After the shipping email really went out (test or live): record what happened on the
// row so the next run leaves it alone. Headings only, matched on 'Order key'.
function nowText() {
  const d = new Date();
  const p = (n) => (n < 10 ? '0' : '') + n;
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' +
         p(d.getHours()) + ':' + p(d.getMinutes());
}
const cfg = $('config').first().json;
const cols = cfg.columns || {};
const h = (k) => cols[k] || k;
const item = $input.first().json;
const out = {};
out[h('order_key')] = String(item[h('order_key')] != null ? item[h('order_key')] : '');
out[h('carrier')] = String(item.carrier || '');
out[h('tracking')] = String(item.tracking || '');
out[h('ship_date')] = String(item.ship_date || '');
out[h('ship_email_sent')] = nowText();
return [{ json: out }];

// A row reached 'Shipped' with no confirmation recorded against it. Never shipped
// unconfirmed: the run stops here and shows the row, instead of emailing a customer
// whose order we cannot prove was confirmed. In the sheet, the fix is to send the
// confirmation (or correct the row) — the gate does not guess.
const cols = $('config').first().json.columns || {};
const h = (k) => cols[k] || k;
const item = $input.first().json;
return (item.unconfirmed || []).map(function (row) {
  return { json: Object.assign({}, row, {
    _outcome: 'held',
    _reason: 'flipped to Shipped but Confirmation sent is blank on the board'
  }) };
});

// Nothing on the board needs this run: no rows flipped to Shipped that are waiting on an
// email, nothing shipped before it was confirmed. The run still completes cleanly.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, { _outcome: 'nothing_to_do' })
}));
